import tripol.time
func sum_range(n:int,swap:bool)->int {
    total=0
    i=0
    while i<n {
        if swap and i%2==0 {total+=i} else {total+=2*i}
        i+=1
    }
    return total
}
n=input_int()
start=time.now_ns()
answer=sum_range(n,true)
ns=time.elapsed_ns(start)
show answer
show "TRIPOL_NS:",ns

